-- Resource articles + counseling intake form become admin-editable content
-- (previously hardcoded), plus a homepage toggle for the journal tagline
-- button.

ALTER TABLE "SiteSettings" ADD COLUMN "hideJournalTaglineButton" BOOLEAN NOT NULL DEFAULT false;

CREATE TABLE "Article" (
    "id" TEXT NOT NULL,
    "slug" TEXT NOT NULL,
    "title" TEXT NOT NULL,
    "excerpt" TEXT NOT NULL,
    "category" TEXT NOT NULL,
    "readMinutes" INTEGER NOT NULL DEFAULT 5,
    "sections" JSONB NOT NULL,
    "checkIns" JSONB NOT NULL,
    "references" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],
    "sortOrder" INTEGER NOT NULL DEFAULT 0,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "Article_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "Article_slug_key" ON "Article"("slug");

CREATE TABLE "IntakeFormConfig" (
    "id" TEXT NOT NULL DEFAULT 'singleton',
    "sections" JSONB NOT NULL,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "IntakeFormConfig_pkey" PRIMARY KEY ("id")
);

